import type { ContextRequestRecord } from "@reina/protocol";
import type { TFunc } from "../../lib/i18n";
import { contextInputMetrics } from "../../lib/contextUsage";
export { contextCategories } from "../../lib/contextUsage";

/** Translate display labels generated by Reina, preserving tool names and
 * unknown future labels verbatim. The saved request content is never translated. */
export function contextSectionLabel(id: string, fallback: string, t: TFunc): string {
  return ["system", "messages", "reminders", "tools", "observations"].includes(id) ? t(`context.section.${id}`) : fallback;
}

export function contextItemLabel(sectionId: string, item: { id: string; label: string }, t: TFunc): string {
  if (item.id === `${sectionId}-omitted` && item.label === "Remaining items") return t("context.remainingItems");
  if (sectionId === "system" && item.id === "system") return t("context.category.system");
  if (sectionId === "messages") {
    const match = /^(\d+)\. (system|user|assistant|tool)$/.exec(item.label);
    if (match) return t("context.messageLabel", { index: match[1]!, role: t(`context.role.${match[2]}`) });
  }
  if (sectionId === "reminders") {
    const match = /^Reminder (\d+)$/.exec(item.label);
    if (match) return t("context.reminderLabel", { index: match[1]! });
  }
  return item.label;
}

export function contextInputTokens(request: ContextRequestRecord): number {
  return contextInputMetrics(request.breakdown, request.usage).input;
}

/** Requests have equal visual spacing. Place compaction between its adjacent
 * requests by timestamp, including compactions after the newest request. */
export function contextEventPosition(requests: ContextRequestRecord[], createdAt: string): number {
  const time = Date.parse(createdAt);
  if (!requests.length || !Number.isFinite(time)) return 0;
  const next = requests.findIndex((request) => Date.parse(request.startedAt) >= time);
  if (next === 0) return 0;
  if (next === -1) return requests.length;
  const before = Date.parse(requests[next - 1]!.startedAt);
  const after = Date.parse(requests[next]!.startedAt);
  const fraction = after > before ? (time - before) / (after - before) : 0.5;
  return next - 0.5 + Math.max(0, Math.min(1, fraction));
}

/** Only lifecycle telemetry for the selected engine triggers a disk reload;
 * token deltas and another task's telemetry are intentionally ignored. */
export function isContextHistoryEvent(raw: unknown, sessionId: string, taskId: string | null): boolean {
  if (!raw || typeof raw !== "object") return false;
  const envelope = raw as { type?: string; sessionId?: string; event?: unknown };
  if (envelope.sessionId !== sessionId) return false;
  if (envelope.type === "session_snapshot") return true;
  if (envelope.type !== "model_stream") return false;
  let inner = envelope.event as { type?: string; taskId?: string; event?: unknown } | undefined;
  if (taskId) {
    if (inner?.type !== "subagent-event" || inner.taskId !== taskId) return false;
    inner = inner.event as typeof inner;
  }
  return inner?.type === "context-request" || inner?.type === "context-history-event";
}

export function formatContextTokens(value: number): string {
  const count = Number.isFinite(value) ? Math.max(0, value) : 0;
  if (count >= 1_000_000) return `${(count / 1_000_000).toFixed(1)}M`;
  if (count >= 1_000) return `${(count / 1_000).toFixed(1)}k`;
  return String(Math.round(count));
}
